INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss das Gateway immer eine IPv6-Adresse haben?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei IPv6-Netzen nötig"}, {"text": "Ja", "correct": false, "because": "IPv4-Netze funktionieren auch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse konfigurierst du für das Gateway in einem IPv6-Netz?', 3, '[{"text": "Link-Local-Adresse", "correct": true, "because": "FE80:: mit Interface"}, {"text": "Globale Unicast-Adresse", "correct": false, "because": "Optional, nicht Pflicht"}, {"text": "Multicast-Adresse", "correct": false, "because": "Nicht für Gateway"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen nutzt du für die Gateway-Konfiguration?', 5, '[{"text": "Statische IPv6-Adresse", "correct": true, "because": "Manuelle Zuweisung"}, {"text": "DHCPv6-Client", "correct": true, "because": "Dynamische Adresse"}, {"text": "DNS-Server-Adresse", "correct": false, "because": "Separat konfiguriert"}, {"text": "Portnummern", "correct": false, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCPv6 kann das Gateway konfigurieren. b) IPv6-Gateways brauchen keine MAC-Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "MAC für Schicht 2 nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Gateway-Konfiguration?', 4, '[{"text": "Link-Local-Adresse", "correct": false, "because": "Standard für IPv6"}, {"text": "Routing-Tabelle", "correct": false, "because": "Definiert Weiterleitung"}, {"text": "Webserver-Port", "correct": true, "because": "Nicht Gateway-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCPv6 das Gateway automatisch setzt?', 2, '[{"text": "Ja", "correct": true, "because": "Option im Protokoll"}, {"text": "Nein", "correct": false, "because": "Typischerweise enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für das Gateway?', 3, '[{"text": "FE80::1", "correct": true, "because": "Link-Local mit Interface"}, {"text": "FF02::1", "correct": false, "because": "Multicast, nicht Gateway"}, {"text": "2001:db8::1", "correct": false, "because": "Global, nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden konfigurieren das Gateway?', 5, '[{"text": "Manuelle Eingabe", "correct": true, "because": "Statische Adresse"}, {"text": "Router Advertisement", "correct": true, "because": "SLAAC liefert Gateway"}, {"text": "Multicast-Ping", "correct": false, "because": "Diagnose, nicht Konfiguration"}, {"text": "HTTP-Anfrage", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) IPv6-Gateways nutzen Link-Local. b) DHCPv6 ist Pflicht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCPv6 optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Gateway-Konfiguration?', 4, '[{"text": "IPv6-Adresse", "correct": false, "because": "Kern der Konfiguration"}, {"text": "Interface-ID", "correct": false, "because": "Für Link-Local nötig"}, {"text": "FTP-Zugangsdaten", "correct": true, "because": "Nicht Gateway-bezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Gateway-Adresse immer global?', 2, '[{"text": "Nein", "correct": true, "because": "Link-Local reicht"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend global"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt DHCPv6 bei der Gateway-Konfiguration?', 4, '[{"text": "Liefert Gateway-Adresse", "correct": true, "because": "Option im Protokoll"}, {"text": "Setzt DNS-Server", "correct": false, "because": "Zusätzliche Option"}, {"text": "Konfiguriert NAT", "correct": false, "because": "Router-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IPv6-Gateways keine Konfiguration brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mindestens Link-Local nötig"}, {"text": "Ja", "correct": false, "because": "Konfiguration erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Gateway-Konfiguration?', 3, '[{"text": "Korrekte IPv6-Adresse", "correct": true, "because": "Routing hängt davon ab"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}, {"text": "Schnelle Antwortzeit", "correct": false, "because": "Diagnose-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Router Advertisement setzt das Gateway. b) DHCPv6 ist immer statisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCPv6 ist dynamisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DHCPv6 fürs Gateway?', 5, '[{"text": "Automatische Adresszuweisung", "correct": true, "because": "Vereinfacht Konfiguration"}, {"text": "Gateway-Option", "correct": true, "because": "Liefert Standardroute"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Keine Verschlüsselung"}, {"text": "Geringe Latenz", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Gateway-Konfiguration unwichtig?', 3, '[{"text": "Link-Local-Adresse", "correct": false, "because": "Standard für IPv6"}, {"text": "Routing-Protokoll", "correct": false, "because": "Definiert Weiterleitung"}, {"text": "Web-UI-Design", "correct": true, "because": "Nicht technisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht jedes Gerät die Gateway-Adresse?', 3, '[{"text": "Ja", "correct": true, "because": "Für externe Kommunikation"}, {"text": "Nein", "correct": false, "because": "Lokale Kommunikation ausgenommen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SLAAC das Gateway setzt?', 2, '[{"text": "Ja", "correct": true, "because": "Via Router Advertisement"}, {"text": "Nein", "correct": false, "because": "Teil der Autokonfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine dynamische Gateway-Adresse?', 4, '[{"text": "DHCPv6", "correct": true, "because": "Liefert Gateway-Option"}, {"text": "Statische Eingabe", "correct": false, "because": "Nicht dynamisch"}, {"text": "Multicast-Abfrage", "correct": false, "because": "Diagnose, nicht Konfiguration"}]');
